<?php
function e($v): string { return htmlspecialchars((string) $v, ENT_QUOTES, 'UTF-8'); }
function money($n): string { return '₱' . number_format((float) $n, 2); }
function flash(string $type, string $msg): void { $_SESSION['flash'] = ['type' => $type, 'msg' => $msg]; }
function csrf(): string { return $_SESSION['csrf'] ??= bin2hex(random_bytes(16)); }
function csrf_field(): string { return '<input type="hidden" name="csrf" value="' . csrf() . '">'; }
function csrf_check(): void { if (!hash_equals($_SESSION['csrf'] ?? '', $_POST['csrf'] ?? '')) { http_response_code(419); die('Session expired. Go back and try again.'); } }
function period_label(string $p): string { return date('F Y', strtotime($p . '-01')); }

// Pure billing logic: free-water tenants never pay water.
function calc_bill(array $t, float $kwh, float $m3, array $rates): array {
    $electric = $kwh * $rates['elec'];
    $free = $t['water_plan'] === 'free';
    $water = $free ? 0 : $m3 * $rates['water'];
    return ['rent' => $t['rent'], 'kwh' => $kwh, 'm3' => $free ? 0 : $m3, 'electric' => $electric, 'water' => $water, 'total' => $t['rent'] + $electric + $water];
}
// Colour binding: success=green (paid/approved/available) | warning=amber (pending/maintenance) | danger=rose (rejected/owing) | info=sky (occupied/metered) | neutral=slate
function badge(string $v): string {
    $m = ['Available'=>'success','Occupied'=>'info','Maintenance'=>'warning','pending'=>'warning','approved'=>'success','rejected'=>'danger','cancelled'=>'neutral','Settled'=>'success','Free water'=>'success','Metered'=>'info','Cash'=>'neutral','Owing'=>'danger'];
    return '<span class="badge badge-' . ($m[$v] ?? 'info') . '">' . e(ucfirst($v)) . '</span>';
}
function initials(string $n): string {
    $f = function_exists('mb_substr') ? 'mb_substr' : 'substr'; $p = preg_split('/\s+/', trim($n)) ?: [''];
    return strtoupper($f($p[0], 0, 1) . (count($p) > 1 ? $f(end($p), 0, 1) : ''));
}
function fdate(string $d): string { return date('M j, Y', strtotime($d)); }
function paginate(array $rows, int $per = 6): array {
    $total = count($rows); $pages = max(1, (int) ceil($total / $per)); $page = min($pages, max(1, (int) ($_GET['page'] ?? 1)));
    return [array_slice($rows, ($page - 1) * $per), $total, $pages, $page];
}
function qs(array $extra): string { return '?' . http_build_query(array_merge($_GET, $extra)); }
